// Golden vectors, step 1: copies the rule methods out of the upstream C# files, unchanged, into golden/gen/Upstream.g.cs,
// wrapped in small classes that stand in for the Fusion objects around them. The upstream gameplay files cannot be
// compiled whole outside Unity (they are NetworkBehaviours full of sprites and Photon callbacks), but the rule methods
// themselves only need a few fields; those are declared here. The generated file is not checked in (it is upstream
// code, with upstream names); `npm run golden` makes it from the upstream checkout and dotnet compiles it.
//
//   node golden/extract.ts [upstream repository root]      (default: the clone this port lives in, ../../..)

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { argv } from "node:process";
import { fileURLToPath } from "node:url";

const here = fileURLToPath(new URL(".", import.meta.url));
const root = resolve(argv[2] ?? join(here, "..", "..", ".."));
const scripts = join(root, "Assets", "Scripts");
const read = (name: string) => readFileSync(join(scripts, name), "utf8").replace(/\r\n/g, "\n");

const spawner = read("Network/BasicSpawner.cs");
const player = read("Player.cs");
const map = read("ShipMap.cs");
const ns = /namespace\s+([A-Za-z0-9_.]+)/.exec(player)![1]!;
/** The upstream field holding the jobs per player, read from the method that uses it (its name is upstream's). */
const jobsField = /Mathf\.Clamp\((_\w+), 0, availableTaskCount\)/.exec(spawner)![1]!;

/** The member whose declaration matches `head` (a regular expression source), through its closing brace. */
function member(source: string, head: string): string {
  const m = new RegExp(`\\n([ \\t]*)((?:public|private|internal)[^\\n;{=]*?\\b${head})`).exec(source);
  if (!m) throw new Error(`not found in upstream: ${head}`);
  const start = m.index + 1;
  let i = source.indexOf("{", start);
  const arrow = source.indexOf("=>", start);
  if (arrow >= 0 && (i < 0 || arrow < i)) return source.slice(start, source.indexOf(";", arrow) + 1); // expression-bodied
  let depth = 0;
  for (; i < source.length; i++) {
    if (source[i] === "{") depth++;
    else if (source[i] === "}" && --depth === 0) return source.slice(start, i + 1);
  }
  throw new Error(`unbalanced: ${head}`);
}

const spawnerMembers = [
  "struct ChannelState",
  "int GetEjectedPlayerNumber\\(",
  "bool CheckWinCondition\\(",
  "bool AreCrewTasksComplete\\(",
  "void GetCrewTaskProgress\\(",
  "int CreateTaskAssignmentMask\\(",
  "void Shuffle<T>\\(",
  "VentStation GetNextVent\\(",
  "void UpdateCircuitTask\\(",
  "void UpdateCalibrationTask\\(",
  "void CommitTaskChannel\\(",
  "void CompleteTaskChannel\\(",
  "void AdvanceChannel\\(",
  "void CancelHeldInteract\\(",
].map((h) => member(spawner, h));

const playerMembers = [
  "int CompletedTaskCount",
  "float KillCooldownRemaining",
  "bool IsKillReady",
  "bool CanDoTasks",
  "bool HasAssignedTask\\(",
  "bool HasCompletedTask\\(",
  "bool CompleteTask\\(",
  "bool AssignTask\\(",
  "static int CountTasks\\(",
].map((h) => member(player, h));

const mapMembers = [
  "static Vector2 ResolveMove\\(",
  "static Vector2 ClampToWalkable\\(",
  "static Vector2 GetRandomWalkablePosition\\(",
  "static Vector2 GetNavigationTarget\\(",
  "static bool HasClearWalkableSegment\\(",
  "static bool IsBlocked\\(",
  "static Vector2 FindNearestOpenPosition\\(",
  "static Vector2 ClampToBounds\\(",
].map((h) => member(map, h));

const constants = ["CircuitPulseCount", "CalibrationTargetStart", "CalibrationTargetEnd"].map((name) => {
  const m = new RegExp(`\\n\\s*(private const [^\\n]*\\b${name}\\b[^\\n]*;)`).exec(spawner);
  if (!m) throw new Error(`constant ${name} not found`);
  return m[1]!;
});

const out = `// GENERATED by golden/extract.ts from the upstream repository. Not checked in. Upstream code is MIT (see README).
using System;
using System.Collections.Generic;
using UnityEngine;

namespace ${ns}
{
    public partial class SpawnerCore
    {
${constants.map((c) => "        " + c).join("\n")}
${spawnerMembers.join("\n\n")}
    }

    public partial class Player
    {
${playerMembers.join("\n\n")}
    }

    public static partial class ShipMapCore
    {
${mapMembers.join("\n\n")}
    }
}
`;

const bridge = `// GENERATED by golden/extract.ts. The plain-typed face Harness.cs calls, so the harness needs no upstream names.
global using static ${ns}.Bridge;
using System;
using System.Collections.Generic;
using UnityEngine;

namespace ${ns}
{
    public class StandIn { public bool HasStateAuthority = true; }

    public partial class Player
    {
        public int PlayerNumber;
        public bool IsBot;
        public PlayerRole Role;
        public MatchState MatchState = (MatchState)1;
        public bool IsAlive = true;
        public int AssignedTaskMask;
        public int AssignedTaskCount;
        public int CompletedTaskMask;
        public int LastAssignedTaskId = -1;
        public bool TaskDeadlineFailed;
        public float LastKillTime;
        public float _killCooldownSeconds = 10f;
        public Vector2 NetworkedPosition;
        public StandIn Object = new StandIn();
        public const int SkipVoteTarget = -1;
        public int Completions;
        public void SetInteraction(InteractionKind kind, float progress, float required) { }
        public void ClearInteraction() { }
    }

    public partial class SpawnerCore
    {
        public readonly Dictionary<int, int> _votes = new Dictionary<int, int>();
        private readonly Dictionary<int, ChannelState> _channels = new Dictionary<int, ChannelState>();
        public bool _taskFailurePending;
        public float _taskDeadlineEndsAt;
        public int _timedTaskWavesIssued;
        public int _maxTimedTaskWaves = 2;
        public int ${jobsField} = 5;
        public float _calibrationCycleSeconds = 2.2f;
        public float _taskChannelSeconds = 1.35f;
        public List<Player> Players = new List<Player>();
        public static TaskStation[] TaskStations = new TaskStation[22];
        public static VentStation[] VentStations = new VentStation[0];
        public string Outcome = "none";
        private List<Player> GetSpawnedPlayers() => new List<Player>(Players);
        private void EndRound(WinningTeam team) { Outcome = "end:" + (int)team; }
        private void BeginTaskFailureCutIn() { Outcome = "cutin"; }
        private bool TryCompleteTask(Player p) { p.Completions++; return true; }
        public int Eject() => GetEjectedPlayerNumber();
        public bool Win() => CheckWinCondition();
        public int Mask() => CreateTaskAssignmentMask();
        public static void ShuffleList<T>(IList<T> items) => Shuffle(items);
        public static int NextVent(int index)
        {
            var next = new SpawnerCore().GetNextVent(VentStations[index]);
            return Array.FindIndex(VentStations, v => v.Position == next.Position);
        }
        public void Tap(Player p, int stationId, float dt, bool held) => UpdateCircuitTask(p, TaskStations[stationId], dt, held);
        public void Timing(Player p, int stationId, float dt, bool held) => UpdateCalibrationTask(p, TaskStations[stationId], dt, held);
        public void Hold(Player p, int stationId, float dt, bool held)
        {
            if (!held) { CancelHeldInteract(p); return; }
            AdvanceChannel(p, (InteractionKind)1, stationId, _taskChannelSeconds, dt, () => TryCompleteTask(p));
        }
        public float Progress(Player p) => _channels.TryGetValue(p.PlayerNumber, out var c) ? c.Progress : -1f;
    }

    public class MapData
    {
        public Rect PlayBounds;
        public RoomArea[] Rooms = new RoomArea[0];
        public Rect[] RoomBounds = new Rect[0];
        public Rect[] Corridors = new Rect[0];
        public Rect[] Doorways = new Rect[0];
        public Rect[] Obstacles = new Rect[0];
        public Vector2[] NavigationWaypoints = new Vector2[0];
        public Vector2 MeetingPoint;
    }

    public static partial class ShipMapCore
    {
        public static MapData Map = new MapData();
        public static Vector2 MeetingPoint => Map.MeetingPoint;
        public static bool Blocked(Vector2 p, float r) => IsBlocked(p, r);
    }

    public static class Bridge
    {
        public static Player NewPlayer(int number, int role, bool alive, int assigned, int completed)
        {
            return new Player { PlayerNumber = number, Role = (PlayerRole)role, IsAlive = alive, AssignedTaskMask = assigned, AssignedTaskCount = CountOf(assigned), CompletedTaskMask = completed };
        }
        static int CountOf(int mask) { var n = 0; for (var i = 0; i < 30; i++) if ((mask & (1 << i)) != 0) n++; return n; }
        public static int Eject(IList<int[]> ballots)
        {
            var core = new SpawnerCore();
            foreach (var b in ballots) core._votes[b[0]] = b[1];
            return core.Eject();
        }
        public static string Win(int[] roles, bool[] alive, int[] assigned, int[] completed, bool failurePending, float deadline, int waves, int maxWaves)
        {
            var core = new SpawnerCore { _taskFailurePending = failurePending, _taskDeadlineEndsAt = deadline, _timedTaskWavesIssued = waves, _maxTimedTaskWaves = maxWaves };
            for (var i = 0; i < roles.Length; i++) core.Players.Add(NewPlayer(i + 1, roles[i], alive[i], assigned[i], completed[i]));
            var ended = core.Win();
            return (ended ? "1" : "0") + " " + core.Outcome;
        }
        public static int[] Deal(int players, int tasks, int stations)
        {
            SpawnerCore.TaskStations = new TaskStation[stations];
            var order = new List<int>();
            for (var i = 1; i <= players; i++) order.Add(i);
            SpawnerCore.ShuffleList(order);
            var core = new SpawnerCore { ${jobsField} = tasks };
            var result = new List<int>(order);
            for (var i = 0; i < players; i++) result.Add(core.Mask());
            return result.ToArray();
        }
        public static float KillRemaining(float cooldown, float lastKill)
        {
            var p = new Player { _killCooldownSeconds = cooldown, LastKillTime = lastKill };
            return p.KillCooldownRemaining;
        }
        public static bool KillReady(float cooldown, float lastKill)
        {
            var p = new Player { _killCooldownSeconds = cooldown, LastKillTime = lastKill };
            return p.IsKillReady;
        }
        /// kind: 0 hold, 1 tap, 2 timing. Returns the index of the step on which the job completed, or -1, and the progress left.
        public static string Channel(int kind, bool bot, float[] dts, bool[] held)
        {
            SpawnerCore.TaskStations = new TaskStation[22];
            SpawnerCore.TaskStations[7] = new TaskStation(7, "", (TaskKind)kind, Vector2.zero);
            var core = new SpawnerCore();
            var p = new Player { PlayerNumber = 1, IsBot = bot, Role = (PlayerRole)1 };
            for (var i = 0; i < dts.Length; i++)
            {
                if (kind == 0) core.Hold(p, 7, dts[i], held[i]);
                else if (kind == 1) core.Tap(p, 7, dts[i], held[i]);
                else core.Timing(p, 7, dts[i], held[i]);
                if (p.Completions > 0) return i + " " + core.Progress(p).ToString("R", System.Globalization.CultureInfo.InvariantCulture);
            }
            return "-1 " + core.Progress(p).ToString("R", System.Globalization.CultureInfo.InvariantCulture);
        }
        static Rect R(float[] a) => new Rect(a[0], a[1], a[2], a[3]);
        public static void LoadMap(float[] bounds, float[][] rooms, float[][] corridors, float[][] obstacles, float[][] waypoints, float[] meeting, float[][] vents, string[] ventGroups)
        {
            var m = new MapData { PlayBounds = R(bounds), MeetingPoint = new Vector2(meeting[0], meeting[1]) };
            m.RoomBounds = Array.ConvertAll(rooms, R);
            m.Rooms = Array.ConvertAll(rooms, a => new RoomArea("", "", R(a), Vector2.zero));
            m.Corridors = Array.ConvertAll(corridors, R);
            m.Obstacles = Array.ConvertAll(obstacles, R);
            m.NavigationWaypoints = Array.ConvertAll(waypoints, a => new Vector2(a[0], a[1]));
            ShipMapCore.Map = m;
            var vs = new VentStation[vents.Length];
            for (var i = 0; i < vents.Length; i++) vs[i] = new VentStation("", ventGroups[i], new Vector2(vents[i][0], vents[i][1]));
            SpawnerCore.VentStations = vs;
        }
        public static bool Blocked(float x, float y, float r) => ShipMapCore.Blocked(new Vector2(x, y), r);
        public static bool Segment(float ax, float ay, float bx, float by, float r) => ShipMapCore.HasClearWalkableSegment(new Vector2(ax, ay), new Vector2(bx, by), r);
        public static float[] Resolve(float x, float y, float dx, float dy, float r) { var v = ShipMapCore.ResolveMove(new Vector2(x, y), new Vector2(dx, dy), r); return new[] { v.x, v.y }; }
        public static float[] Nav(float x, float y, float tx, float ty) { var v = ShipMapCore.GetNavigationTarget(new Vector2(x, y), new Vector2(tx, ty)); return new[] { v.x, v.y }; }
        public static float[] RandomPoint() { var v = ShipMapCore.GetRandomWalkablePosition(); return new[] { v.x, v.y }; }
        public static int NextVent(int i) => SpawnerCore.NextVent(i);
    }
}
`;

const gen = join(here, "gen");
mkdirSync(gen, { recursive: true });
writeFileSync(join(gen, "Upstream.g.cs"), out.replace(/ShipMap\.(?=HasClearWalkableSegment|GetNavigationTarget)/g, "ShipMapCore."));
writeFileSync(join(gen, "Bridge.g.cs"), bridge);
console.log(`extracted ${spawnerMembers.length + playerMembers.length + mapMembers.length} members from ${scripts}`);
